#include "DustAccumulationMaterial.h"
// Note: GenericOctave.h not available in UE5.8; using built-in Perlin noise instead

UDustAccumulationMaterial::UDustAccumulationMaterial()
	: AccumulationRate(0.5f), DecayRate(0.2f), NormalThreshold(0.7f), CurrentAccumulation(0.0f)
{
}

float UDustAccumulationMaterial::GetDustIntensity(FVector VertexNormal, float Time)
{
	// Calculate dust intensity based on vertex normal and procedural noise
	float NormalFactor = FMath::Max(0.0f, VertexNormal.Z); // Z component for horizontal surfaces

	// Simple procedural noise using sin/cos for variation
	float NoiseValue = FMath::Sin(VertexNormal.X * 3.0f) * FMath::Cos(VertexNormal.Y * 5.0f);
	NoiseValue = (NoiseValue + 1.0f) * 0.5f; // Normalize to [0, 1]

	// Combine normal factor and noise for final intensity
	float Intensity = (NormalFactor * AccumulationRate) + (NoiseValue * 0.3f);
	Intensity = FMath::Clamp(Intensity, 0.0f, 1.0f);

	return Intensity;
}

void UDustAccumulationMaterial::ApplyNoiseMask(float NoiseScale, float NoiseFrequency)
{
	// Apply procedural noise mask for dust accumulation
	// This would be connected to material parameters in Blueprint or via MCP pathways
CurrentAccumulation = FMath::FInterpTo(CurrentAccumulation,
		CurrentAccumulation + (AccumulationRate * NoiseScale),
		1.0f, DecayRate);

	UE_LOG(LogTemp, Display, TEXT("DustAccumulationMaterial: Applied noise mask with scale %f and frequency %f"), NoiseScale, NoiseFrequency);
}